(require '[clojure.string :as str] '[clojure.edn :as edn])
(def project (System/getenv "KOTOBASE_ORACLE_ROOT"))
(load-string (first (str/split (slurp (str project "/oracle/awai-174/governed_linked_registry_memory.clj")) #"\(let \[before \(memory/snapshot memory-backend\)" 2)))
(require '[kotobase.storage.core :as storage] '[awai.fs.car :as car] '[kotobase.authority-commit-attestation :as attest])
(import '[java.security MessageDigest] '[java.util Random Arrays])
(def base (System/getenv "LINKED_GOVERNED_BASE"))
(def backend (fb/open-backend (str base "/store") (str base "/stage") tool))
(def database (core/open {:storage backend :encrypt-fn identity :decrypt-fn identity :blind-fn pr-str :visible? (constantly true)}))
(def prior-ids (edn/read-string (slurp (str base "/deny-ids.edn"))))
(def ids (edn/read-string (slurp (str base "/auth-ids.edn"))))
(def records (:receipt/records (causal/receipt-at database (:commit ids) (:cid ids))))
(assert (= (:commit ids) (:cid (storage/-read-ref backend "linked-governed-auth"))))
(assert (= (:commit prior-ids) (:cid (storage/-read-ref backend "linked-governed-denied"))))
(assert (= (:commit prior-ids) (:receipt/basis-cid (causal/receipt-at database (:commit ids) (:cid ids)))))
(assert (= 3 (count (:receipt/records (causal/receipt-at database (:commit prior-ids) (:cid prior-ids))))))
(assert (= 3 (count records)))
(assert (= :allow (:authority/decision (first records))))
(def authority-seed (vec (repeat 32 5)))
(def authority-entry {:key/id "authority" :key/algorithm :ed25519 :key/material (ed/public-key authority-seed)})
(def auth-verifier (attest/verifier {:attestation (:attestation ids) :registry (fn [scope] (if (= scope {:role :issuer :tenant tenant :epoch 7}) [authority-entry] [])) :algorithm :ed25519 :issuer-authorized? (fn [{:keys [issuer key]}] (and (= issuer "did:key:fixture-authority") (= (:key/id key) "authority"))) :verify-with (fn [{:keys [key payload-cid signature-value]}] (ed/verify (:key/material key) (payload-bytes payload-cid) signature-value))}))
(def authenticate (causal/decision-receipt-authenticator database {:commit-cid (:authority-commit ids) :verify-commit! auth-verifier}))
(def request* (assoc request :nonce "linked-governed-forest-auth-04"))
(assert (true? (authenticate {:authority-receipt (second records) :request request* :query query})))
(assert (try (authenticate {:authority-receipt (assoc (second records) :causal.receipt/principal "wrong") :request request* :query query}) false (catch Exception _ true)))
(def no-key-verifier (attest/verifier {:attestation (:attestation ids) :registry (constantly []) :algorithm :ed25519 :issuer-authorized? (constantly true) :verify-with (constantly true)}))
(def no-key-authenticate (causal/decision-receipt-authenticator database {:commit-cid (:authority-commit ids) :verify-commit! no-key-verifier}))
(assert (try (no-key-authenticate {:authority-receipt (second records) :request request* :query query}) false (catch Exception _ true)))
(assert (true? (ed/verify (ed/public-key executor) (payload-bytes (id/payload-cid (first records))) (get-in (first records) [:signature :signature/value]))))
(assert (true? (link/verify! {:link (nth records 2) :request request* :query query :execution-receipt (first records) :authority-receipt (second records) :value-cid id/value-cid :verify (:verify opts)})))
(def rng (Random. 174532))
(dotimes [_ 2] (let [b (byte-array (* 600 1024)) _ (.nextBytes rng b) d (mapv #(bit-and 255 %) (.digest (MessageDigest/getInstance "SHA-256") b)) cid (car/cid-str (car/cid-bytes car/codec-raw d))] (assert (Arrays/equals ^bytes b ^bytes (storage/get-block backend cid)))))
(prn {:fresh-process :verified :authority-attestation :verified :unregistered-issuer :rejected :tampered-authority :rejected :execution-signature :verified :new-ref :verified :prior-ref :verified :prior-basis :verified :records 3 :link :verified :attachments :verified :pass true})
(shutdown-agents)
